"""Triton implementation of aten::l1_loss (none / mean / sum reductions).

Design notes
------------
* ``|x - y|`` is formed in the operand dtype (matching ATen, which subtracts in
  the promoted input dtype) and upcast to fp32 for reduction, so only the final
  result is rounded into the promoted output dtype and half/bf16 inputs never
  round twice.
* Both operands are pushed into the broadcast shape ``S`` (N = prod(S)) and the
  element mapping is expressed with expanded element strides, so contiguous
  same-shape inputs take a pure 1-D fast path while transposed / broadcast
  inputs use the generic strided path.  No input copy is ever materialised.
* Reductions run as one partial-sum tile per program (the shape validated by
  the target backend's own reduction kernels) followed by a single-program
  finalize kernel that reduces the fp32 partials and applies ``1/N``.
"""

import numbers
from contextlib import nullcontext

import torch
import triton
import triton.language as tl

_MAX_RANK = 8
_BLOCK = 2048
_FINALIZE_BLOCK = 1024


@triton.jit
def _l1_loss_flat_kernel(
    x_ptr,
    y_ptr,
    out_ptr,
    n_elements,
    MODE: tl.constexpr,
    WIDE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    if WIDE:
        offsets = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    else:
        offsets = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offsets < n_elements
    x = tl.load(x_ptr + offsets, mask=mask, other=0.0)
    y = tl.load(y_ptr + offsets, mask=mask, other=0.0)
    diff = tl.abs(x - y)
    if MODE == 0:
        tl.store(out_ptr + offsets, diff.to(out_ptr.dtype.element_ty), mask=mask)
    else:
        tl.store(out_ptr + pid, tl.sum(diff.to(tl.float32), axis=0))


@triton.jit
def _l1_loss_reduce_flat_kernel(
    x_ptr,
    y_ptr,
    out_ptr,
    n_elements,
    scale,
    SINGLE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Persistent split reduction: one fp32 partial per launched program.

    Each program streams several tiles with a BLOCK-wide fp32 vector
    accumulator, so the horizontal reduction and the partial store are paid
    once per program instead of once per 2048-element tile.  With a single
    launched program the finalize step is fused here (SINGLE=True) and the
    scaled result is written straight to the 0-dim output.
    """
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    acc = tl.zeros([BLOCK], dtype=tl.float32)
    lane = tl.arange(0, BLOCK)
    n_tiles = n_elements // BLOCK
    n_full = n_tiles * BLOCK
    for off in range(pid * BLOCK, n_full, nprog * BLOCK):
        x = tl.load(x_ptr + off + lane)
        y = tl.load(y_ptr + off + lane)
        acc += tl.abs(x - y).to(tl.float32)
    if n_full < n_elements and (n_tiles % nprog) == pid:
        offs = n_full + lane
        mask = offs < n_elements
        x = tl.load(x_ptr + offs, mask=mask, other=0.0)
        y = tl.load(y_ptr + offs, mask=mask, other=0.0)
        acc += tl.abs(x - y).to(tl.float32)
    total = tl.sum(acc, axis=0)
    if SINGLE:
        tl.store(out_ptr, total * scale)
    else:
        tl.store(out_ptr + pid, total)


@triton.jit
def _l1_loss_generic_kernel(
    x_ptr,
    y_ptr,
    out_ptr,
    n_elements,
    p0,
    p1,
    p2,
    p3,
    p4,
    p5,
    p6,
    p7,
    xs0,
    xs1,
    xs2,
    xs3,
    xs4,
    xs5,
    xs6,
    xs7,
    ys0,
    ys1,
    ys2,
    ys3,
    ys4,
    ys5,
    ys6,
    ys7,
    RANK: tl.constexpr,
    MODE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = offsets < n_elements
    rem = offsets
    xoff = tl.zeros([BLOCK], dtype=tl.int64)
    yoff = tl.zeros([BLOCK], dtype=tl.int64)
    if RANK >= 1:
        d = rem % p7
        rem = rem // p7
        xoff += d * xs7
        yoff += d * ys7
    if RANK >= 2:
        d = rem % p6
        rem = rem // p6
        xoff += d * xs6
        yoff += d * ys6
    if RANK >= 3:
        d = rem % p5
        rem = rem // p5
        xoff += d * xs5
        yoff += d * ys5
    if RANK >= 4:
        d = rem % p4
        rem = rem // p4
        xoff += d * xs4
        yoff += d * ys4
    if RANK >= 5:
        d = rem % p3
        rem = rem // p3
        xoff += d * xs3
        yoff += d * ys3
    if RANK >= 6:
        d = rem % p2
        rem = rem // p2
        xoff += d * xs2
        yoff += d * ys2
    if RANK >= 7:
        d = rem % p1
        rem = rem // p1
        xoff += d * xs1
        yoff += d * ys1
    if RANK >= 8:
        d = rem % p0
        rem = rem // p0
        xoff += d * xs0
        yoff += d * ys0
    x = tl.load(x_ptr + xoff, mask=mask, other=0.0)
    y = tl.load(y_ptr + yoff, mask=mask, other=0.0)
    diff = tl.abs(x - y)
    if MODE == 0:
        tl.store(out_ptr + offsets, diff.to(out_ptr.dtype.element_ty), mask=mask)
    else:
        tl.store(out_ptr + pid, tl.sum(diff.to(tl.float32), axis=0))


@triton.jit
def _l1_loss_finalize_kernel(part_ptr, out_ptr, n_parts, scale, BLOCK: tl.constexpr):
    acc = tl.zeros([BLOCK], dtype=tl.float32)
    for start in range(0, n_parts, BLOCK):
        offs = start + tl.arange(0, BLOCK)
        mask = offs < n_parts
        acc += tl.load(part_ptr + offs, mask=mask, other=0.0)
    total = tl.sum(acc, axis=0) * scale
    tl.store(out_ptr, total)


@triton.jit
def _l1_loss_fill_kernel(out_ptr, value):
    tl.store(out_ptr, value)


def _normalize_reduction(reduction):
    """Accept 0/1/2 and 'none'/'mean'/'sum' (any case)."""
    if isinstance(reduction, str):
        key = reduction.lower()
        if key == "none":
            return 0
        if key == "mean":
            return 1
        if key == "sum":
            return 2
        raise ValueError(f"Invalid reduction: {reduction!r}")
    if isinstance(reduction, numbers.Integral) and not isinstance(reduction, bool):
        value = int(reduction)
        if value in (0, 1, 2):
            return value
        raise ValueError(f"Invalid reduction: {reduction!r}")
    raise ValueError(f"Unsupported reduction type: {type(reduction)!r}")


def _device_ctx(device):
    try:
        if device.type == "npu":
            return torch.npu.device(device)
    except Exception:
        pass
    return nullcontext()


def _vector_core_count(device_index):
    """Runtime vector-core count; no hard-coded device constant."""
    try:
        from triton.runtime import driver

        if device_index is None:
            device_index = torch.npu.current_device()
        props = driver.active.utils.get_device_properties(int(device_index))
        count = int(props["num_vectorcore"])
        return count if count > 0 else None
    except Exception:
        return None


def _program_count(tiles, device_index):
    if tiles <= 0:
        return 0
    cap = _vector_core_count(device_index)
    if cap is None:
        return tiles
    return min(tiles, cap)


def _expanded_strides(tensor, shape):
    pad = len(shape) - tensor.dim()
    strides = (0,) * pad + tuple(tensor.stride())
    sizes = (1,) * pad + tuple(tensor.shape)
    return tuple(
        0 if (size == 1 and out_size != 1) else stride
        for size, out_size, stride in zip(sizes, shape, strides)
    )


def _collapse_dims(shape, x_strides, y_strides):
    """Drop size-1 axes and merge axes that stay dense in both operands."""
    dims = [
        (int(size), int(xs), int(ys))
        for size, xs, ys in zip(shape, x_strides, y_strides)
        if int(size) != 1
    ]
    if not dims:
        return [(1, 0, 0)]
    merged = [dims[-1]]
    for size, xs, ys in reversed(dims[:-1]):
        inner_size, inner_xs, inner_ys = merged[-1]
        if xs == inner_xs * inner_size and ys == inner_ys * inner_size:
            merged[-1] = (size * inner_size, inner_xs, inner_ys)
        else:
            merged.append((size, xs, ys))
    merged.reverse()
    if len(merged) > _MAX_RANK:
        raise NotImplementedError(
            "l1_loss: broadcast rank exceeds the supported maximum"
        )
    return merged


def _generic_args(dims):
    rank = len(dims)
    pad = _MAX_RANK - rank
    sizes = [1] * pad + [d[0] for d in dims]
    x_strides = [0] * pad + [d[1] for d in dims]
    y_strides = [0] * pad + [d[2] for d in dims]
    return rank, sizes + x_strides + y_strides


def l1_loss(self, target, reduction=1):
    red = _normalize_reduction(reduction)
    if self.device != target.device:
        raise AssertionError("l1_loss: input and target must be on the same device.")

    out_dtype = torch.promote_types(self.dtype, target.dtype)
    shape = torch.broadcast_shapes(tuple(self.shape), tuple(target.shape))
    n_elements = 1
    for size in shape:
        n_elements *= int(size)

    device = self.device
    block = _BLOCK
    tiles = (n_elements + block - 1) // block if n_elements > 0 else 0
    wide = n_elements >= (1 << 31)
    fast = (
        tuple(self.shape) == shape
        and tuple(target.shape) == shape
        and self.is_contiguous()
        and target.is_contiguous()
    )

    with _device_ctx(device):
        if red == 0:
            out = torch.empty(shape, dtype=out_dtype, device=device)
            if n_elements == 0:
                return out
            if fast:
                _l1_loss_flat_kernel[(tiles,)](
                    self,
                    target,
                    out,
                    n_elements,
                    MODE=0,
                    WIDE=wide,
                    BLOCK=block,
                )
            else:
                dims = _collapse_dims(
                    shape,
                    _expanded_strides(self, shape),
                    _expanded_strides(target, shape),
                )
                rank, extra = _generic_args(dims)
                _l1_loss_generic_kernel[(tiles,)](
                    self,
                    target,
                    out,
                    n_elements,
                    *extra,
                    RANK=rank,
                    MODE=0,
                    BLOCK=block,
                )
            return out

        out = torch.empty((), dtype=out_dtype, device=device)
        if n_elements == 0:
            fill = float("nan") if red == 1 else 0.0
            _l1_loss_fill_kernel[(1,)](out, fill)
            return out

        scale = (1.0 / n_elements) if red == 1 else 1.0
        if fast and tiles <= 2:
            # Small workload: one program covers every tile, so the finalize
            # step is fused and only a single kernel is launched.
            _l1_loss_reduce_flat_kernel[(1,)](
                self,
                target,
                out,
                n_elements,
                scale,
                SINGLE=True,
                BLOCK=block,
            )
            return out
        n_parts = _program_count(tiles, device.index) if fast else tiles
        partials = torch.empty(n_parts, dtype=torch.float32, device=device)
        if fast:
            _l1_loss_reduce_flat_kernel[(n_parts,)](
                self,
                target,
                partials,
                n_elements,
                1.0,
                SINGLE=False,
                BLOCK=block,
            )
        else:
            dims = _collapse_dims(
                shape,
                _expanded_strides(self, shape),
                _expanded_strides(target, shape),
            )
            rank, extra = _generic_args(dims)
            _l1_loss_generic_kernel[(n_parts,)](
                self,
                target,
                partials,
                n_elements,
                *extra,
                RANK=rank,
                MODE=1,
                BLOCK=block,
            )
        _l1_loss_finalize_kernel[(1,)](
            partials,
            out,
            n_parts,
            scale,
            BLOCK=_FINALIZE_BLOCK,
        )
        return out
